import { MakeLogicType, actions, kea, path, reducers } from 'kea'

import { uuid } from 'lib/utils/dom'
import { permanentlyMount } from 'lib/utils/kea-logic-builders'

import { AnyPropertyFilter } from '~/types'

import { FilterBarSavedSet } from './filterBarTypes'

export const MAX_SAVED_FILTER_SETS = 20

const teamId = typeof window !== 'undefined' ? window.POSTHOG_APP_CONTEXT?.current_team?.id : undefined

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface filterBarSavedSetsLogicValues {
    savedSets: FilterBarSavedSet[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface filterBarSavedSetsLogicActions {
    deleteSavedSet: (id: string) => {
        id: string
    }
    saveSet: (
        name: string,
        filters: AnyPropertyFilter[]
    ) => {
        name: string
        filters: AnyPropertyFilter[]
    }
}

export type filterBarSavedSetsLogicType = MakeLogicType<filterBarSavedSetsLogicValues, filterBarSavedSetsLogicActions>

/**
 * Filter sets a person named and kept, shared by every filter bar in the project. They live in local storage
 * because the bar is behind a flag and no backend model exists for them yet.
 */
export const filterBarSavedSetsLogic = kea<filterBarSavedSetsLogicType>([
    path(['lib', 'components', 'FilterBar', 'filterBarSavedSetsLogic']),
    actions({
        saveSet: (name: string, filters: AnyPropertyFilter[]) => ({ name, filters }),
        deleteSavedSet: (id: string) => ({ id }),
    }),
    reducers({
        savedSets: [
            [] as FilterBarSavedSet[],
            { persist: true, prefix: `${teamId}__` },
            {
                saveSet: (state, { name, filters }) => {
                    const trimmed = name.trim()
                    if (!trimmed || filters.length === 0) {
                        return state
                    }
                    const entry: FilterBarSavedSet = { id: uuid(), name: trimmed, filters, createdAt: Date.now() }
                    return [entry, ...state.filter((set) => set.name !== trimmed)].slice(0, MAX_SAVED_FILTER_SETS)
                },
                deleteSavedSet: (state, { id }) => state.filter((set) => set.id !== id),
            },
        ],
    }),
    permanentlyMount(),
])
